"""Plain-language presentation; detection results and evidence remain unchanged."""
# title, why it matters, uncertainty, next step
GUIDES = {
'brute_force': ('Several login attempts failed', 'Someone repeatedly tried to sign in from one address.', 'Password mistakes and automated jobs can look similar.', 'Ask the account owner about these attempts and inspect the surrounding login events.'),
'brute_force_escalated': ('A larger burst of login failures', 'The number of failed attempts reached the higher review threshold.', 'This may be the same activity as another login-failure finding, not a separate attack.', 'Review the related failures together and check whether a successful login followed.'),
'account_takeover': ('A login succeeded after repeated failures', 'The same account and source had failures before a successful sign-in.', 'The account owner may have corrected a password; this does not prove an account was stolen.', 'Confirm the successful login with the owner and review what the account did afterward.'),
'suspicious_ip': ('An address matches your configured watch list', 'The project configuration includes this address as a review indicator.', 'This is a static list match, not a live reputation check or proof of malicious behavior.', 'Check why the address is on the list and assess the actual events from it.'),
'unusual_time': ('A login happened outside its usual hours', 'The login time differs from the available reference pattern for this user and computer.', 'Travel, shift changes and limited training data can explain unusual hours.', 'Check the reference source in the technical details and ask whether the login time was expected.'),
'country_change': ('A user has different reported login countries', 'The supplied country information differs across successful login evidence.', 'Country information can be inaccurate or affected by VPNs; this does not prove impossible travel.', 'Verify the location data and ask the owner whether those connections were expected.'),
'privilege_escalation': ('A command changed elevated-access settings', 'A command appears to change privileged groups, permissions or access policy.', 'An authorized administrator may make these changes; successful execution is not established.', 'Confirm the change request and inspect the resulting permissions or group membership.'),
'suspicious_powershell': ('PowerShell used an encoded command', 'Encoding can make a command harder to inspect.', 'Legitimate tools also encode commands; encoding alone does not establish harm.', 'Inspect the command safely as text and compare it with expected software activity.'),
'lolbin_execution': ('A system tool used a download or execution pattern', 'A built-in utility was used in a pattern worth reviewing.', 'Administrators may use the same utilities for legitimate tasks.', 'Check the full command, target and related process evidence before deciding.'),
'c2_beaconing': ('Repeated outbound check-ins need review', 'The logs show a check-in signal or timing pattern that may represent an automated connection.', 'Updates and legitimate agents can behave this way; this is not confirmed attacker communication.', 'Identify the process and destination and compare them with approved software.'),
'data_exfiltration': ('An outbound transfer has suspicious context', 'The transfer evidence meets the current rule criteria, such as an archive and a configured destination.', 'The logs do not prove which bytes were transferred or that sensitive data left the computer.', 'Verify the destination, transfer outcome, file contents and authorization.'),
'network_scan': ('One source probed several network ports', 'Several destination ports were contacted in a short window.', 'An approved scanner can cause the same pattern; a blocked probe does not show successful access.', 'Check whether scanning was scheduled and inspect the firewall evidence.'),
'web_attack': ('A web request contains an attack-like payload', 'The request contains a pattern such as SQL-like text, a script payload or directory traversal.', 'A request pattern or HTTP success code does not prove the application was exploited.', 'Inspect the request and response, then compare with application or endpoint logs.'),
'post_auth_download_execute': ('A file was downloaded, made executable and launched', 'Commands for the same file appear after a login with suspicious context.', 'Authorized installation can look similar; the log records commands rather than their verified effects.', 'Confirm the session with the owner and inspect the downloaded file and execution outcome.'),
'distributed_authentication': ('Many addresses tried to sign in to one computer', 'Failed logins are spread across several source addresses and accounts.', 'Shared services or fleet automation can generate many failures.', 'Check the accounts and sources together and compare with expected automation.'),
'slow_authentication': ('Login failures continued over a longer period', 'One source tried several accounts across a prolonged time window.', 'Misconfigured software or an authorized test may explain the pattern.', 'Review the full time window and check whether the source and targeted accounts were expected.'),
'success_after_source_failures': ('A source signed in after prolonged failures', 'The same source address had a longer pattern of failures before this successful login.', 'The failed accounts may differ from the successful account; this is not confirmed account takeover.', 'Confirm this login with its owner and inspect subsequent activity.'),
'upload_command_request': ('An upload was followed by a command-like web request', 'The same source contacted an uploaded script with a command parameter soon after an accepted upload.', 'The upload filename and actual execution are unverified; shared addresses can represent different clients.', 'Inspect the uploaded file, application records and process logs to verify what happened.'),
'sensitive_file_read': ('A command requested access to password-hash data', 'The command attempts to read or copy /etc/shadow, which can contain password hashes.', 'The command may be authorized and the logs do not show whether the read succeeded.', 'Confirm the purpose and check file-access evidence and any destination copy.'),
'account_creation_context': ('An account-creation command followed suspicious activity', 'An account-creation command appeared near earlier authentication or execution findings.', 'Provisioning can be legitimate; the command does not prove an account was successfully created.', 'Verify the request, resulting account and permissions with the system owner.'),
'cron_change_context': ('A scheduled-job editor opened after suspicious activity', 'Cron editing appeared near earlier authentication or execution findings.', 'The editor opening does not show that any scheduled job was saved.', 'Inspect the actual scheduled jobs and confirm any changes were approved.'),
'history_clearing': ('A command requested shell-history clearing', 'Clearing history can remove a record of commands from a shell session.', 'Some maintenance uses this command; it does not erase every source of evidence.', 'Confirm the reason and compare with other session and audit records.'),
'log_clearing': ('A command requested log removal or aggressive pruning', 'Removing logs or keeping almost no journal history can reduce investigation evidence.', 'Authorized maintenance can also prune logs, and execution success is unknown.', 'Check the maintenance policy and retained logs, and record the evidence you still have.'),
'archive_transfer_review': ('An archive was followed by an external transfer command', 'The same archive was referenced by a transfer to an address outside the local ranges checked by the rule.', 'External backups can be legitimate; the destination is not necessarily malicious and transferred bytes are unknown.', 'Confirm the destination and backup approval before classifying the activity.'),
}

def explain(alert):
    title,why,uncertainty,next_step=GUIDES.get(alert.get('type'),('An event needs review','The stored rule flagged this event.','This rule has no specific beginner explanation yet.','Inspect the original finding and source evidence.'))
    return dict(title=title,why=why,uncertainty=uncertainty,next_step=next_step,
                priority={'critical':'Review first','high':'Review soon','medium':'Needs context','low':'Lower priority'}.get(alert.get('severity'),'Needs review'))
